const CHIRP_SIZE = 41;
const FS = 8000; // Sample rate

class LPCSynth {
  constructor() {
    this.ctx = null;
    this.masterGain = null;
    this.initialized = false;
  }

  init() {
    if (this.initialized) return;
    this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    this.masterGain = this.ctx.createGain();
    this.masterGain.gain.value = 0.5;
    this.masterGain.connect(this.ctx.destination);
    this.initialized = true;
  }

  async resume() {
    if (this.ctx && this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }
  }

  /**
   * Reverse bits in a byte - TMS5100 ROM data is bit-reversed
   */
  rev(a) {
    a = ((a >> 4) | (a << 4)) & 0xFF;
    a = (((a & 0xCC) >> 2) | ((a & 0x33) << 2)) & 0xFF;
    a = (((a & 0xAA) >> 1) | ((a & 0x55) << 1)) & 0xFF;
    return a;
  }

  /**
   * Decode and synthesize LPC data - direct port of Talkie's ISR
   */
  decodeLPC(data) {
    const samples = [];
    
    // Bit reading state
    let ptrAddr = 0;
    let ptrBit = 0;

    const getBits = (bits) => {
      let value;
      let d = this.rev(data[ptrAddr]) << 8;
      if (ptrBit + bits > 8 && ptrAddr + 1 < data.length) {
        d |= this.rev(data[ptrAddr + 1]);
      }
      d <<= ptrBit;
      value = (d >> (16 - bits)) & ((1 << bits) - 1);
      ptrBit += bits;
      if (ptrBit >= 8) {
        ptrBit -= 8;
        ptrAddr++;
      }
      return value;
    };

    // Synthesis state - matches Talkie's global variables
    let synthPeriod = 0;
    let synthEnergy = 0;
    let synthK1 = 0, synthK2 = 0;
    let synthK3 = 0, synthK4 = 0, synthK5 = 0, synthK6 = 0, synthK7 = 0, synthK8 = 0, synthK9 = 0, synthK10 = 0;

    // Filter state
    let x0 = 0, x1 = 0, x2 = 0, x3 = 0, x4 = 0, x5 = 0, x6 = 0, x7 = 0, x8 = 0, x9 = 0;
    
    // Excitation state
    let periodCounter = 0;
    let synthRand = 1;

    // Process frames
    let frameCount = 0;
    while (ptrAddr < data.length && frameCount < 500) {
      frameCount++;
      
      // Read frame header
      const energy = getBits(4);
      
      if (energy === 0) {
        // Energy = 0: rest frame
        synthEnergy = 0;
      } else if (energy === 0xF) {
        // Energy = 15: stop frame
        synthEnergy = 0;
        synthK1 = synthK2 = synthK3 = synthK4 = synthK5 = 0;
        synthK6 = synthK7 = synthK8 = synthK9 = synthK10 = 0;
        break;
      } else {
        synthEnergy = tmsEnergy[energy];
        const repeat = getBits(1);
        synthPeriod = tmsPeriod[getBits(6)];
        
        if (!repeat) {
          // All frames use first 4 coefficients
          synthK1 = toSigned16(tmsK1[getBits(5)]);
          synthK2 = toSigned16(tmsK2[getBits(5)]);
          synthK3 = toSigned8(tmsK3[getBits(4)]);
          synthK4 = toSigned8(tmsK4[getBits(4)]);
          
          if (synthPeriod) {
            // Voiced frames use 6 extra coefficients
            synthK5 = toSigned8(tmsK5[getBits(4)]);
            synthK6 = toSigned8(tmsK6[getBits(4)]);
            synthK7 = toSigned8(tmsK7[getBits(4)]);
            synthK8 = toSigned8(tmsK8[getBits(3)]);
            synthK9 = toSigned8(tmsK9[getBits(3)]);
            synthK10 = toSigned8(tmsK10[getBits(3)]);
          }
        }
      }

      // Render samples for this frame (25ms = 200 samples at 8kHz)
      for (let i = 0; i < 200; i++) {
        let u0, u1, u2, u3, u4, u5, u6, u7, u8, u9, u10;

        // Generate excitation
        if (synthPeriod) {
          // Voiced source
          if (periodCounter < synthPeriod) {
            periodCounter++;
          } else {
            periodCounter = 0;
          }
          if (periodCounter < CHIRP_SIZE) {
            u10 = (chirp[periodCounter] * synthEnergy) >> 8;
          } else {
            u10 = 0;
          }
        } else {
          // Unvoiced source (noise)
          synthRand = (synthRand >> 1) ^ ((synthRand & 1) ? 0xB800 : 0);
          u10 = (synthRand & 1) ? synthEnergy : -synthEnergy;
        }

        // Lattice filter forward path
        u9 = u10 - ((synthK10 * x9) >> 7);
        u8 = u9 - ((synthK9 * x8) >> 7);
        u7 = u8 - ((synthK8 * x7) >> 7);
        u6 = u7 - ((synthK7 * x6) >> 7);
        u5 = u6 - ((synthK6 * x5) >> 7);
        u4 = u5 - ((synthK5 * x4) >> 7);
        u3 = u4 - ((synthK4 * x3) >> 7);
        u2 = u3 - ((synthK3 * x2) >> 7);
        u1 = u2 - ((synthK2 * x1) >> 15);
        u0 = u1 - ((synthK1 * x0) >> 15);

        // Output clamp
        if (u0 > 511) u0 = 511;
        if (u0 < -512) u0 = -512;

        // Lattice filter reverse path
        x9 = x8 + ((synthK9 * u8) >> 7);
        x8 = x7 + ((synthK8 * u7) >> 7);
        x7 = x6 + ((synthK7 * u6) >> 7);
        x6 = x5 + ((synthK6 * u5) >> 7);
        x5 = x4 + ((synthK5 * u4) >> 7);
        x4 = x3 + ((synthK4 * u3) >> 7);
        x3 = x2 + ((synthK3 * u2) >> 7);
        x2 = x1 + ((synthK2 * u1) >> 15);
        x1 = x0 + ((synthK1 * u0) >> 15);
        x0 = u0;

        // Convert to float (-1 to 1)
        samples.push(u0 / 512);
      }
    }

    return samples;
  }

  /**
   * Play LPC encoded word data
   */
  playWord(data) {
    const samples = this.decodeLPC(data);
    if (samples.length === 0) return 0;

    // Create buffer at native sample rate
    const nativeSamples = Math.ceil(samples.length * this.ctx.sampleRate / FS);
    const buffer = this.ctx.createBuffer(1, nativeSamples, this.ctx.sampleRate);
    const output = buffer.getChannelData(0);
    
    // Upsample with sample-and-hold for authentic sound
    const ratio = FS / this.ctx.sampleRate;
    for (let i = 0; i < nativeSamples; i++) {
      const srcIdx = Math.floor(i * ratio);
      output[i] = samples[Math.min(srcIdx, samples.length - 1)];
    }

    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(this.masterGain);
    source.start();
    
    return buffer.duration;
  }

  /**
   * Pre-render speech for a text and play it over a specified duration
   * @param {string} text - Text to speak
   * @param {number} duration - Duration in seconds to stretch/compress playback
   */
  speakOverDuration(text, duration) {
    if (!this.initialized) this.init();
    this.resume();

    // Generate samples for the text
    const samples = this.generateSpeechSamples(text);
    if (samples.length === 0) return;

    // Calculate playback rate to match typing duration
    const naturalDuration = samples.length / FS;
    const playbackRate = naturalDuration / duration;

    // Create buffer at native sample rate
    const nativeSamples = Math.ceil(samples.length * this.ctx.sampleRate / FS);
    const buffer = this.ctx.createBuffer(1, nativeSamples, this.ctx.sampleRate);
    const output = buffer.getChannelData(0);
    
    const ratio = FS / this.ctx.sampleRate;
    for (let i = 0; i < nativeSamples; i++) {
      const srcIdx = Math.floor(i * ratio);
      output[i] = samples[Math.min(srcIdx, samples.length - 1)];
    }

    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.value = playbackRate;
    source.connect(this.masterGain);
    source.start();
  }

  /**
   * Get LPC data for a word from VOCAB, handling both formats:
   * - Single: VOCAB[word] = [0x00, 0x01, ...] (built-in Talkie data)
   * - Multi:  VOCAB[word] = [[0x00,...], [0x00,...]] (generated multi-voice)
   */
  getWordData(word) {
    const entry = VOCAB[word];
    if (!entry) return null;
    
    // Check if it's multi-variant (array of arrays) or single (array of numbers)
    if (Array.isArray(entry[0])) {
      // Multi-variant: pick a random one
      return entry[Math.floor(Math.random() * entry.length)];
    }
    // Single variant
    return entry;
  }

  /**
   * Check if a word exists in the vocabulary
   * @param {string} word - Word to check (will be lowercased)
   * @returns {boolean}
   */
  hasWord(word) {
    return VOCAB.hasOwnProperty(word.toLowerCase());
  }

  /**
   * Get audio samples for a single word
   * @param {string} word - Word to synthesize
   * @returns {Float32Array|null} - Audio samples at 8kHz, or null if word not found
   */
  getWordSamples(word) {
    const wordData = this.getWordData(word.toLowerCase());
    if (!wordData) return null;
    return this.decodeLPC(wordData);
  }

  /**
   * Get the sample rate for LPC audio
   * @returns {number} - Sample rate in Hz
   */
  getSampleRate() {
    return 8000;
  }

  /**
   * Generate speech samples for arbitrary text
   */
  generateSpeechSamples(text) {
    const words = text.toLowerCase().split(/\s+/);
    const allSamples = [];
    
    for (const word of words) {
      let samples;
      const wordData = this.getWordData(word);
      if (wordData) {
        samples = this.decodeLPC(wordData);
      } else {
        // Unknown word - concatenate random vocab fragments
        const syllables = Math.max(1, Math.ceil(word.length / 3));
        samples = [];
        const vocabKeys = Object.keys(VOCAB).filter(k => k !== 'pause');
        for (let i = 0; i < syllables; i++) {
          const randomKey = vocabKeys[Math.floor(Math.random() * vocabKeys.length)];
          const randomData = this.getWordData(randomKey);
          const wordSamples = this.decodeLPC(randomData);
          // Take a portion of the word
          const portion = Math.floor(wordSamples.length * (0.3 + Math.random() * 0.4));
          const start = Math.floor(Math.random() * (wordSamples.length - portion));
          samples.push(...wordSamples.slice(start, start + portion));
        }
      }
      allSamples.push(...samples);
      
      // Add small pause between words (400 samples = 50ms at 8kHz)
      for (let i = 0; i < 400; i++) {
        allSamples.push(0);
      }
    }
    
    return allSamples;
  }

  /**
   * Speak a single character - plays a short phoneme sound
   */
  speakChar(char) {
    if (!this.initialized) this.init();
    this.resume();

    const lower = char.toLowerCase();
    
    // Skip spaces and punctuation (silent)
    if (!/[a-z]/.test(lower)) return;

    // Pick a vocabulary word to use as the sound source
    // Vowels get vowel-heavy words, consonants get consonant-heavy words
    const vowels = 'aeiou';
    const isVowel = vowels.includes(lower);
    
    // Use a random word from vocab and play just a portion of it
    const vocabKeys = Object.keys(VOCAB).filter(k => k !== 'pause');
    const word = vocabKeys[Math.floor(Math.random() * vocabKeys.length)];
    
    this.playWordFragment(VOCAB[word], isVowel);
  }

  /**
   * Play a short fragment of a word (for per-character speech)
   */
  playWordFragment(data, isVowel) {
    const samples = this.decodeLPC(data);
    if (samples.length === 0) return;

    // Take just 1-3 frames worth of samples (50-150ms)
    const frameCount = isVowel ? 2 + Math.floor(Math.random() * 2) : 1 + Math.floor(Math.random() * 2);
    const samplesToUse = Math.min(frameCount * 200, samples.length);
    
    // Random start position within the word
    const maxStart = Math.max(0, samples.length - samplesToUse);
    const startIdx = Math.floor(Math.random() * maxStart);
    const fragment = samples.slice(startIdx, startIdx + samplesToUse);

    // Apply short fade in/out to avoid clicks
    const fadeLen = Math.min(20, fragment.length / 4);
    for (let i = 0; i < fadeLen; i++) {
      fragment[i] *= i / fadeLen;
      fragment[fragment.length - 1 - i] *= i / fadeLen;
    }

    // Create buffer
    const nativeSamples = Math.ceil(fragment.length * this.ctx.sampleRate / FS);
    const buffer = this.ctx.createBuffer(1, nativeSamples, this.ctx.sampleRate);
    const output = buffer.getChannelData(0);
    
    const ratio = FS / this.ctx.sampleRate;
    for (let i = 0; i < nativeSamples; i++) {
      const srcIdx = Math.floor(i * ratio);
      output[i] = fragment[Math.min(srcIdx, fragment.length - 1)];
    }

    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(this.masterGain);
    source.start();
  }

  /**
   * Speak text - finds words in vocabulary or plays random words
   */
  speak(text) {
    if (!this.initialized) this.init();
    this.resume();

    const words = text.toLowerCase().split(/\s+/);
    let delay = 0;

    for (const word of words) {
      const wordData = this.getWordData(word);
      if (wordData) {
        setTimeout(() => this.playWord(wordData), delay * 1000);
        delay += 0.5;
      } else {
        // Word not in vocab - play random vocab words
        const syllables = Math.max(1, Math.ceil(word.length / 3));
        const vocabKeys = Object.keys(VOCAB).filter(k => k !== 'pause');
        for (let i = 0; i < syllables; i++) {
          const randomKey = vocabKeys[Math.floor(Math.random() * vocabKeys.length)];
          const randomData = this.getWordData(randomKey);
          setTimeout(() => this.playWord(randomData), delay * 1000);
          delay += 0.35;
        }
      }
    }
  }

  setVolume(value) {
    if (this.masterGain) {
      this.masterGain.gain.value = Math.max(0, Math.min(1, value));
    }
  }
}

const lpcSynth = new LPCSynth();
export default lpcSynth;
export { LPCSynth, VOCAB };
